WITH ValidTransactions AS (SELECT * FROM transactions WHERE account_id IN (34, 37) AND txn_time < '2024-07-06'), agg AS (SELECT QUARTER(txn_time) txn_quarter, account_id, ROUND(STDDEV(amount), 2) stddev_amount, SORT_ARRAY(COLLECT_SET(merchant)) merchant_list FROM ValidTransactions GROUP BY QUARTER(txn_time), account_id) SELECT * FROM agg WHERE stddev_amount >= 26 ORDER BY account_id DESC, stddev_amount ASC
